static void upsert(Session s, String slug, String content) {
    Article a = s.createQuery("from Article where slug = :slug", Article.class).setParameter("slug", slug).uniqueResultOptional().orElse(null);
    if (a == null) { a = new Article(); a.setSlug(slug); s.persist(a); }
    a.setContent(content);
}

